/**
 * @file    door.c
 * @brief   The door task's handlers (SPEC-020): each state's returns the state to be in next.
 *
 * @details
 * Generated by emb-hwgen from system.yaml; yours to edit: regeneration merges its changes (A126).
 */
#include "tasks.h"

#include <emb_board.h>

emb_state_t door_on_closed(door_t *self, const emb_task_event_t *ev)
{
    (void)self;
    return (ev->id == DOOR_EV_OPEN) ? DOOR_OPEN : DOOR_CLOSED;
}

emb_state_t door_on_open(door_t *self, const emb_task_event_t *ev)
{
    (void)self;
    if (ev->id == EMB_EV_TIMEOUT) { /* open for its two seconds: it closes itself */
        emb_board_puts("door: closing by itself\n");
        return DOOR_CLOSED;
    }
    if (ev->id == DOOR_EV_JAM) {
        return DOOR_JAMMED;
    }
    return (ev->id == DOOR_EV_CLOSE) ? DOOR_CLOSED : DOOR_OPEN;
}

emb_state_t door_on_jammed(door_t *self, const emb_task_event_t *ev)
{
    (void)self;
    return (ev->id == DOOR_EV_CLOSE) ? DOOR_CLOSED : DOOR_JAMMED;
}

void door_enter_open(door_t *self)
{
    self->data.count++;
    emb_board_puts("door: open\n");
}

void door_exit_open(door_t *self)
{
    (void)self;
    emb_board_puts("door: closed\n");
}
